initJs:
function(container, apiUrl, tables) {
  let currentProducts = [];
  let stores = [];
  let demandForecasts = [];
  let currentInventory = [];

  // テーブルインデックス
  const STORE_TABLE = 1; // 店舗マスタ
  const PRODUCT_TABLE = 2; // 商品マスタ
  const DEMAND_FORECAST_TABLE = 8; // 需要予測結果
  const ORDER_TABLE = 9; // 発注データ

  // 商品テーブル再描画関数
  function renderProducts(products) {
    const tbody = container.querySelector("#product-tbody");

    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted); padding: 40px;">該当する商品が見つかりませんでした</td></tr>';
      return;
    }

    tbody.innerHTML = products.map(product => {
      const forecast = demandForecasts.find(f => f.商品ID === product.id) || {};
      const inventory = Math.floor(Math.random() * 100) + 10; // 模擬在庫データ
      const predictedDemand = forecast.予測数量 || Math.floor(Math.random() * 50) + 10;
      const recommendedOrder = Math.max(0, predictedDemand - inventory);

      return `
        <tr data-id="${product.id}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${getCategoryName(product.商品カテゴリID)}</td>
          <td>${inventory}</td>
          <td>${predictedDemand}</td>
          <td>${recommendedOrder}</td>
          <td>
            <input type="number" class="input order-quantity-input" data-product-id="${product.id}" 
                   value="${recommendedOrder}" min="0" style="width: 80px;">
            <div class="quantity-error hidden" style="color: #ff6a6a; font-size: 12px; margin-top: 2px;"></div>
          </td>
          <td>
            <input type="text" class="input order-reason-input" data-product-id="${product.id}" 
                   placeholder="発注理由" style="width: 120px;">
          </td>
          <td>
            <button class="action-btn order-btn" data-product-id="${product.id}">発注</button>
            <button class="action-btn secondary adjust-btn" data-product-id="${product.id}">調整</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // カテゴリ名取得
  function getCategoryName(categoryId) {
    const categories = {
      'cat1': '食品',
      'cat2': '日用品', 
      'cat3': '衣料品',
      'cat4': '家電'
    };
    return categories[categoryId] || '未分類';
  }

  // 需要予測結果表示
  function renderDemandForecast(storeId) {
    const forecastArea = container.querySelector("#demand-forecast-area");

    if (!storeId) {
      forecastArea.innerHTML = '<p style="color: var(--text-muted);">店舗を選択すると需要予測結果が表示されます</p>';
      return;
    }

    const storeForecast = demandForecasts.filter(f => f.店舗ID === storeId);
    const totalPredicted = storeForecast.reduce((sum, f) => sum + (f.予測数量 || 0), 0);
    const avgAccuracy = storeForecast.length > 0 ? 
      Math.round(storeForecast.reduce((sum, f) => sum + (f.予測精度 || 85), 0) / storeForecast.length) : 85;

    forecastArea.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 15px;">
        <div style="text-align: center;">
          <div style="color: var(--text); font-size: 24px; font-weight: bold;">${totalPredicted}</div>
          <div style="color: var(--text-muted); font-size: 12px;">総予測需要量</div>
        </div>
        <div style="text-align: center;">
          <div style="color: var(--text); font-size: 24px; font-weight: bold;">${avgAccuracy}%</div>
          <div style="color: var(--text-muted); font-size: 12px;">平均予測精度</div>
        </div>
        <div style="text-align: center;">
          <div style="color: var(--text); font-size: 24px; font-weight: bold;">${storeForecast.length}</div>
          <div style="color: var(--text-muted); font-size: 12px;">予測対象商品数</div>
        </div>
      </div>
    `;
  }

  // 店舗選択肢を設定
  function loadStores() {
    window.aivicApi.list(STORE_TABLE).then(storeData => {
      if (storeData) {
        stores = storeData;
        const storeSelect = container.querySelector("#store-select");
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.map(store => `<option value="${store.id}">${store.店舗名}</option>`).join('');
      }
    });
  }

  // 商品データ読み込み
  function loadProducts(storeId = null, categoryFilter = '', searchKeyword = '') {
    window.aivicApi.list(PRODUCT_TABLE).then(productData => {
      if (productData) {
        let filteredProducts = productData.filter(p => p.有効フラグ);

        // カテゴリフィルター
        if (categoryFilter) {
          filteredProducts = filteredProducts.filter(p => getCategoryName(p.商品カテゴリID) === categoryFilter);
        }

        // 検索キーワードフィルター
        if (searchKeyword) {
          const keyword = searchKeyword.toLowerCase();
          filteredProducts = filteredProducts.filter(p => 
            (p.商品名 && p.商品名.toLowerCase().includes(keyword)) ||
            (p.商品コード && p.商品コード.toLowerCase().includes(keyword))
          );
        }

        currentProducts = filteredProducts;
        renderProducts(storeId ? filteredProducts : []);
      }
    });
  }

  // 需要予測データ読み込み
  function loadDemandForecasts() {
    window.aivicApi.list(DEMAND_FORECAST_TABLE).then(forecastData => {
      if (forecastData) {
        demandForecasts = forecastData;
      }
    });
  }

  // バリデーション関数
  function validateDateRange() {
    const startDate = container.querySelector("#date-start").value;
    const endDate = container.querySelector("#date-end").value;
    const errorDiv = container.querySelector("#date-error");

    if (startDate && endDate && startDate > endDate) {
      errorDiv.textContent = "開始日は終了日より前の日付を入力してください";
      errorDiv.classList.remove("hidden");
      return false;
    }

    errorDiv.classList.add("hidden");
    return true;
  }

  function validateOrderQuantity(input) {
    const value = input.value;
    const errorDiv = input.parentElement.querySelector(".quantity-error");

    if (value === '') {
      errorDiv.textContent = "発注量を入力してください";
      errorDiv.classList.remove("hidden");
      return false;
    }

    if (isNaN(value) || value.includes('.')) {
      errorDiv.textContent = "発注量は数値で入力してください";
      errorDiv.classList.remove("hidden");
      return false;
    }

    const numValue = parseInt(value);
    if (numValue < 0) {
      errorDiv.textContent = "発注量は正の数値を入力してください";
      errorDiv.classList.remove("hidden");
      return false;
    }

    if (numValue === 0) {
      errorDiv.textContent = "発注量は1以上を入力してください";
      errorDiv.classList.remove("hidden");
      return false;
    }

    if (numValue > 999999999) {
      errorDiv.textContent = "発注量が上限を超えています";
      errorDiv.classList.remove("hidden");
      return false;
    }

    errorDiv.classList.add("hidden");
    return true;
  }

  // CSVエクスポート
  function exportCSV() {
    window.aivicApi.list(ORDER_TABLE).then(orderData => {
      if (!orderData) return;

      const headers = ['発注ID', '店舗名', '商品名', '発注日', '発注数量', '発注金額', '発注ステータス', '発注理由'];
      const csvContent = '\uFEFF' + headers.join(',') + '\n' +
        orderData.map(order => {
          const store = stores.find(s => s.id === order.店舗ID);
          const product = currentProducts.find(p => p.id === order.商品ID);
          return [
            order.id || '',
            store ? store.店舗名 : '',
            product ? product.商品名 : '',
            order.発注日 || '',
            order.発注数量 || '',
            order.発注金額 || '',
            order.発注ステータス || '',
            (order.発注理由 || '').replace(/,/g, '，')
          ].map(field => `"${field}"`).join(',');
        }).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `発注管理_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 発注処理
  function processOrder(productId, quantity, reason) {
    const storeId = container.querySelector("#store-select").value;
    const product = currentProducts.find(p => p.id === productId);

    if (!storeId) {
      alert("店舗を選択してください");
      return;
    }

    const orderData = {
      店舗ID: storeId,
      商品ID: productId,
      発注日: new Date().toISOString(),
      納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7日後
      発注数量: parseInt(quantity),
      発注単価: product ? product.単価 : 100,
      発注金額: parseInt(quantity) * (product ? product.単価 : 100),
      発注方法: reason ? 'AI推奨修正' : 'AI推奨採用',
      発注ステータス: '発注済',
      発注理由: reason || 'AI需要予測による推奨発注',
      自動発注フラグ: false,
      作成者ID: 'current-user',
      更新者ID: 'current-user'
    };

    window.aivicApi.save(ORDER_TABLE, orderData).then(result => {
      if (result) {
        alert("発注が完了しました");
        // 発注量入力欄をリセット
        const quantityInput = container.querySelector(`input[data-product-id="${productId}"].order-quantity-input`);
        const reasonInput = container.querySelector(`input[data-product-id="${productId}"].order-reason-input`);
        if (quantityInput) quantityInput.value = '';
        if (reasonInput) reasonInput.value = '';
      }
    });
  }

  // 初期データ読み込み
  loadStores();
  loadProducts();
  loadDemandForecasts();

  // イベントリスナー設定

  // 店舗選択変更
  container.querySelector("#store-select").addEventListener("change", (e) => {
    const storeId = e.target.value;
    renderDemandForecast(storeId);

    if (storeId) {
      const categoryFilter = container.querySelector("#category-select").value;
      const searchKeyword = container.querySelector("#product-search").value;
      loadProducts(storeId, categoryFilter, searchKeyword);
    } else {
      renderProducts([]);
    }
  });

  // カテゴリ選択変更
  container.querySelector("#category-select").addEventListener("change", () => {
    const storeId = container.querySelector("#store-select").value;
    const categoryFilter = container.querySelector("#category-select").value;
    const searchKeyword = container.querySelector("#product-search").value;
    loadProducts(storeId, categoryFilter, searchKeyword);
  });

  // 日付範囲バリデーション
  container.querySelector("#date-start").addEventListener("change", validateDateRange);
  container.querySelector("#date-end").addEventListener("change", validateDateRange);

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    if (!validateDateRange()) return;

    const storeId = container.querySelector("#store-select").value;
    const categoryFilter = container.querySelector("#category-select").value;
    const searchKeyword = container.querySelector("#product-search").value;
    loadProducts(storeId, categoryFilter, searchKeyword);
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  // 発注量入力バリデーション
  container.addEventListener("input", (e) => {
    if (e.target.classList.contains("order-quantity-input")) {
      validateOrderQuantity(e.target);
    }
  });

  // 発注・調整ボタンのイベントデリゲーション
  container.addEventListener("click", (e) => {
    const orderBtn = e.target.closest(".order-btn");
    const adjustBtn = e.target.closest(".adjust-btn");

    if (orderBtn) {
      const productId = orderBtn.dataset.productId;
      const quantityInput = container.querySelector(`input[data-product-id="${productId}"].order-quantity-input`);
      const reasonInput = container.querySelector(`input[data-product-id="${productId}"].order-reason-input`);

      if (!validateOrderQuantity(quantityInput)) return;

      const quantity = quantityInput.value;
      const reason = reasonInput.value;

      // 発注確認ダイアログ表示
      const product = currentProducts.find(p => p.id === productId);
      const confirmContent = container.querySelector("#order-confirm-content");
      confirmContent.innerHTML = `
        <p><strong>商品名:</strong> ${product ? product.商品名 : ''}</p>
        <p><strong>発注数量:</strong> ${quantity}</p>
        <p><strong>発注理由:</strong> ${reason || 'AI需要予測による推奨発注'}</p>
      `;

      const dialog = container.querySelector("#order-dialog");
      dialog.classList.remove("hidden");

      // 確定ボタンにproductIdを設定
      container.querySelector("#btn-confirm-order").dataset.productId = productId;
    }

    if (adjustBtn) {
      const productId = adjustBtn.dataset.productId;
      const quantityInput = container.querySelector(`input[data-product-id="${productId}"].order-quantity-input`);

      // 推奨発注量を再設定
      const forecast = demandForecasts.find(f => f.商品ID === productId) || {};
      const inventory = Math.floor(Math.random() * 100) + 10;
      const predictedDemand = forecast.予測数量 || Math.floor(Math.random() * 50) + 10;
      const recommendedOrder = Math.max(0, predictedDemand - inventory);

      quantityInput.value = recommendedOrder;
      validateOrderQuantity(quantityInput);
    }
  });

  // ダイアログのキャンセル・確定
  container.querySelector("#btn-cancel-order").addEventListener("click", () => {
    container.querySelector("#order-dialog").classList.add("hidden");
  });

  container.querySelector("#btn-confirm-order").addEventListener("click", (e) => {
    const productId = e.target.dataset.productId;
    const quantityInput = container.querySelector(`input[data-product-id="${productId}"].order-quantity-input`);
    const reasonInput = container.querySelector(`input[data-product-id="${productId}"].order-reason-input`);

    processOrder(productId, quantityInput.value, reasonInput.value);
    container.querySelector("#order-dialog").classList.add("hidden");
  });
}
